import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { PlaneGeometry, Mesh, Group, SRGBColorSpace, DoubleSide } = ctx.THREE;

  const group = new Group();
  group.name = config.id || 'collection-card-3';

  const atlasX = 0;
  const atlasY = 0;
  const atlasW = 512;
  const atlasH = 320;
  const aspect = atlasW / atlasH;

  const cardHeight = 1.0;
  const cardWidth = cardHeight * aspect;

  const geometry = new PlaneGeometry(cardWidth, cardHeight);

  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true
  });

  let cardTexture = null;
  const timelines = [];

  const imageUrl = config.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';

  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    cardTexture = tex;
    tex.colorSpace = SRGBColorSpace;
    material.map = texture(tex);
    material.needsUpdate = true;
  });

  const sprite = new Mesh(geometry, material);
  sprite.name = 'card-sprite';
  sprite.onBeforeRender = (renderer, scene, camera) => {
    sprite.quaternion.copy(camera.quaternion);
  };
  group.add(sprite);

  group.scale.set(0, 0, 0);
  const entrance = gsap.timeline();
  entrance.to(group.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.7,
    ease: 'power3.out'
  });
  entrance.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  });
  timelines.push(entrance);

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    if (ctx.primitives[primitive.name]) {
      const result = ctx.primitives[primitive.name](group, primitive.params);
      if (result && result.timeline) {
        timelines.push(result.timeline);
      }
    }
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    geometry.dispose();
    material.dispose();
    if (cardTexture) {
      cardTexture.dispose();
    }
  };

  return group;
}
